9	// ── Security: CORS — restrict to localhost origins ────────────────────────────
10	const ALLOWED_ORIGINS = new Set([
11	  'http://localhost:3847',
12	  'http://localhost:5173',   // Vite dev
13	  'http://localhost:3000',
14	  'http://localhost:8080',
15	  'http://127.0.0.1:3847',
16	  'http://127.0.0.1:5173',
17	  'http://127.0.0.1:3000',
18	  'http://127.0.0.1:8080',
19	]);
20	
21	app.use((req, res, next) => {
22	  const origin = req.headers.origin;
23	  if (origin && ALLOWED_ORIGINS.has(origin)) {
24	    res.header('Access-Control-Allow-Origin', origin);
25	  } else if (!origin) {
26	    // Same-origin or server-to-server (no Origin header)
27	    res.header('Access-Control-Allow-Origin', '*');
28	  }
29	  res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
30	  res.header('Access-Control-Allow-Headers', 'Content-Type');
31	  if (req.method === 'OPTIONS') return res.sendStatus(204);
32	  next();
33	});
34	
35	// ── Security: Localhost-only guard ────────────────────────────────────────────
36	app.use((req, res, next) => {
37	  const ip = req.ip || req.connection?.remoteAddress || '';
38	  const isLocal = ip === '127.0.0.1' || ip === '::1' || ip === '::ffff:127.0.0.1' || ip === 'localhost';
39	  if (!isLocal) {
40	    return res.status(403).json({ error: 'Claude Hub is local-only' });
41	  }
42	  next();
43	});
44	
45	// ── Security: Rate limiting (in-memory, simple) ──────────────────────────────
46	const rateLimitMap = new Map();
47	const RATE_LIMIT_WINDOW = 60_000; // 1 minute
48	const RATE_LIMITS = {
49	  heavy: 10,   // AI chat, orchestration runs, playground — 10/min
50	  write: 60,   // file writes, creates, deletes — 60/min
51	  read: 200,   // reads, listings — 200/min
52	};
53	
54	function rateLimit(tier) {
55	  const max = RATE_LIMITS[tier] || RATE_LIMITS.read;
56	  return (req, res, next) => {
57	    const key = `${tier}:${req.ip}`;
58	    const now = Date.now();
59	    let entry = rateLimitMap.get(key);
60	    if (!entry || now - entry.start > RATE_LIMIT_WINDOW) {
61	      entry = { start: now, count: 0 };
62	      rateLimitMap.set(key, entry);
63	    }
64	    entry.count++;
65	    if (entry.count > max) {
66	      return res.status(429).json({ error: `Rate limit exceeded (${max}/${RATE_LIMIT_WINDOW / 1000}s)` });
67	    }
68	    next();
69	  };
70	}
71	
72	// Cleanup stale entries every 5 minutes
73	setInterval(() => {
74	  const now = Date.now();
75	  for (const [key, entry] of rateLimitMap) {
76	    if (now - entry.start > RATE_LIMIT_WINDOW * 2) rateLimitMap.delete(key);
77	  }
78	}, 300_000);
