1452	    const claudePath = process.env.CLAUDE_PATH || 'claude';
1453	    const childEnv = { ...process.env, HOME: os.homedir() };
1454	    delete childEnv.CLAUDECODE;
1455	    const proc = spawn(claudePath, ['-p'], { env: childEnv });
1456	    let out = '', err = '';
1457	    let killed = false;
1458	
1459	    const timer = setTimeout(() => {
1460	      killed = true;
1461	      proc.kill('SIGTERM');
1462	      setTimeout(() => { try { proc.kill('SIGKILL'); } catch {} }, 5000);
1463	    }, timeoutMs);
1464	
1465	    proc.stdout.on('data', d => { out += d.toString(); });
1466	    proc.stderr.on('data', d => { err += d.toString(); });
1467	    proc.on('close', code => {
1468	      clearTimeout(timer);
1469	      if (killed) reject(new Error(`Node execution timed out after ${timeoutMs / 1000}s`));
1470	      else if (code !== 0) reject(new Error(err.trim() || `claude exited ${code}`));
1471	      else resolve(out.trim());
1472	    });
1473	    proc.on('error', (e) => { clearTimeout(timer); reject(e); });
1474	    proc.stdin.write(prompt, 'utf8');
1475	    proc.stdin.end();
